//! Port of `packages/database/__tests__/integration/insert-required-columns.test.ts`
//! (P2.3 spec section 5.1, rows 2.1-2.6). Class C: runs against a migrated SQLite file.
//!
//! `requiredColumns` = NOT NULL, no column default, not generated by the app (`id`).
//! The two `test.each` repository cases (`:216`, `:230`) belong to the repositories unit (P3).

mod common;

use common::{columns, fresh_db, required_columns};

const AUDITED_TABLES: &[&str] = &[
    "ConnectSession",
    "Inbox",
    "IntegrationApi",
    "IntegrationInstagram",
    "IntegrationMessenger",
    "IntegrationWhatsapp",
    "WhatsappSignupSession",
];

/// Port of: packages/database/__tests__/integration/insert-required-columns.test.ts:160 "repository inserts satisfy the real column definitions > every audited table was found in the database"
#[tokio::test]
async fn every_audited_table_was_found_in_the_database() {
    let db = fresh_db().await;
    for table in AUDITED_TABLES {
        assert!(
            !columns(&db, table).await.is_empty(),
            "no columns for {table}"
        );
    }
}

/// Port of: packages/database/__tests__/integration/insert-required-columns.test.ts:253 "repository inserts satisfy the real column definitions > the Inbox columns a connect must supply are still exactly these"
#[tokio::test]
async fn the_inbox_columns_a_connect_must_supply_are_still_exactly_these() {
    let db = fresh_db().await;
    assert_eq!(
        required_columns(&db, "Inbox").await,
        ["channel", "name", "sourceId", "workspaceId"]
    );
}

